import{_ as t,o as n,c as o,au as a,aF as r}from"./chunks/framework.ChGI_eLK.js";import"./chunks/theme.CfmGloal.js";const u=JSON.parse('{"title":"Internal Cooldown","description":"","frontmatter":{},"headers":[],"relativePath":"guide/elements/Internal_Cooldown.md","filePath":"guide/elements/Internal Cooldown.md","lastUpdated":1783267680000}'),s={name:"guide/elements/Internal_Cooldown.md"};function l(i,e,d,p,g,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="Internal_Cooldown" tabindex="-1">Internal Cooldown <a class="header-anchor" href="#Internal_Cooldown" aria-label="Permalink to “Internal Cooldown”">​</a></h1><p><strong>Internal Cooldown</strong>, commonly abbreviated as <strong>ICD</strong>, is a game mechanic that regulates how often an ability can apply an element onto an entity.</p><h2 id="Introduction" tabindex="-1">Introduction <a class="header-anchor" href="#Introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>When dealing elemental damage, we may fully expect that the element would <strong>always</strong> be applied. However, that isn&#39;t always the case.</p><div align="center"><video width="95%" height="auto" controls><source src="'+r+'" type="video/mp4"> Your browser does not support the video tag. </video></div><p>As seen in the video above, despite clearly doing <span class="cryo"><strong>Cryo DMG</strong></span>, the <span style="color:#f2be87;"><strong>Melt</strong></span> reaction isn&#39;t always triggered.</p><p>While it may look like there is no pattern behind it, this is actually due to a mechanic known as Internal Cooldown, or <strong>ICD</strong> for short. For the example, Internal Cooldown <em>regulates</em> when <span class="cryo"><strong>Cryo</strong></span> is applied as an Element, resulting in our <span class="cryo"><strong>Cryo DMG</strong></span> instances to trigger the <span style="color:#f2be87;"><strong>Melt</strong></span> reaction every once in a while, as opposed to every time.</p><p>However, the target still takes <span class="cryo"><strong>Cryo DMG</strong></span>, even when the <span class="cryo"><strong>Cryo</strong></span> element itself isn&#39;t applied.</p><h2 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to “Overview”">​</a></h2><p>Internal Cooldown is handled by two properties:</p><p>Internal Cooldown is based on the attack&#39;s <strong>tag</strong> and <strong>type</strong>, as well as the <strong>entity</strong> that dealt the damage. Attacks from the same entity that share the same <strong>tag</strong> and <strong>type</strong> will share ICD.</p><h2 id="Internal_Cooldown_Type" tabindex="-1">Internal Cooldown Type <a class="header-anchor" href="#Internal_Cooldown_Type" aria-label="Permalink to “Internal Cooldown Type”">​</a></h2><p>    <em>&quot;Internal Cooldown Type&quot; redirects here. For the definiton of Internal Cooldown Types in data packs, see <a href="../../Internal_Cooldown_Type_definition">Internal Cooldown Type definition</a></em>.</p><p>An Internal Cooldown Type contains two properties: the <strong>reset interval</strong> and the <strong>gauge sequence</strong>, commonly denoted as: <strong>(ResetInterval)s/(GaugeSequence) hits</strong>.</p><p>For an Element to be applied by the same ability, either:</p><ul><li>The time from the previous Elemental Application to this Elemental Application exceeds the Internal Cooldown&#39;s <strong>reset interval</strong>, or</li><li>The amount of &quot;hits&quot; from this ability that attempted to apply an Element exceeds the Internal Cooldown&#39;s <strong>gauge sequence</strong>.</li></ul><p>If any of these conditions are fulfilled, the Internal Cooldown is considered to be inactive, allowing the Element to be applied.</p><p>It is also important to note that:</p><ul><li>The first hit after the <strong>gauge sequence</strong> applies an element, but does <strong>not</strong> clear the timer given by the <strong>reset interval</strong>.</li><li>The first hit after the <strong>reset interval</strong> applies an element <strong>and</strong> clears both the timer given by the <strong>reset interval</strong> and the <strong>gauge sequence</strong>.</li></ul><p>In simpler terms, clearing the <strong>gauge sequence</strong> allows you to apply an element without clearing the <strong>reset interval</strong>, effectively &quot;sneaking in&quot; an Elemental application, rewarding fast attackers. Slower attackers unable to clear the <strong>gauge sequence</strong> in time rely instead on the <strong>reset interval</strong>.</p><p>Most abilities in Genshin Impact follow the standard ICD of <strong>2.5s</strong>/<strong>3</strong> hits, represented in Seven Elements as <code>seven-elements:default</code>. Elemental Attacks that have a cooldown may also choose to have no ICD instead, represented in Seven Elements as <code>seven-elements:none</code>.</p>',21)])])}const w=t(s,[["render",l]]);export{u as __pageData,w as default};
